(() => {
  const observations={"s1": {"tag": "사진 형상 반영", "title": "S1 · 검은 캡과 노출 코일 현가", "text": "왼쪽 위 모듈의 검은 원형 캡, 노출 코일 스프링과 주변 금속 지지부를 캐스터 현가 형상에 적용했습니다. 중앙 가이드와 포크는 기구 해석을 반영한 개념 형상입니다. 정확한 치수·피벗 위치는 추정입니다.", "part": "caster"}, "s2": {"tag": "사진 형상 반영", "title": "S2 · 두 번째 코일 스프링 현가", "text": "오른쪽 아래에도 검은 캡 아래 금속 코일이 보입니다. 이 두 모듈을 전방 좌우 현가 캐스터로 설계에 적용했습니다. 사진의 원근을 고려해 실제 XY좌표와 장착 높이는 추정 치수로 두었습니다.", "part": "caster"}, "battery": {"tag": "사진 라벨 확인", "title": "B · 14S4P 배터리와 은색 고정대", "text": "원본 사진 화면 오른쪽의 검은 직사각형 팩의 Holiday Robotics 로고와 14S4P 표기를 반영했습니다. 14직렬·4병렬, 총 56셀 구성입니다. 팩의 은색 고정대를 반영했습니다. 공식 교체 영상과 대조해 로봇 좌측(+Y) 슬롯·상향 인출로 배치를 수정했습니다. 셀 화학계·형식·용량·정확한 팩 외형은 미확인입니다.", "part": "battery"}, "round": {"tag": "식별 보류", "title": "R · 치형 원형 전달부품", "text": "회색 원형 면과 외주 치형이 보이지만 바닥 접촉이 드러나지 않습니다. 이 부품을 접지휠 개수에 포함하지 않았습니다. 정확한 전달계 구성은 후속 확인 대상입니다."}};
  function showObservation(key){const o=observations[key];document.querySelectorAll('[data-observation]').forEach(b=>{const on=b.dataset.observation===key;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});$('observation-detail').innerHTML=`<div><span class="pill ${key==='round'?'assumption':'observed'}">${o.tag}</span><h3>${o.title}</h3></div><p>${o.text}</p>`;if(o.part)select(o.part);}
  document.querySelectorAll('[data-observation]').forEach(b=>b.addEventListener('click',()=>showObservation(b.dataset.observation)));
  $('annotations').addEventListener('change',()=>{$('photo-markers').hidden=!$('annotations').checked;});
  function springPoints(x,y0,y1,r=8,turns=5){const pts=[[x,y0]];for(let i=0;i<=turns*12;i++){const t=i/(turns*12);pts.push([x+Math.sin(t*Math.PI*2*turns)*r,y0+(y1-y0)*t]);}pts.push([x,y1]);return pts.map(p=>p.join(',')).join(' ');}
  function diagram(P,Nd,Nc,span,pivot,F,valid){
    const xD=130,xC=570,yG=260,xP=xD+(xC-xD)*suspension.pivotPct/100,xS=xP-(xC-xD)*suspension.lever/span;
    const forceHeight=n=>Math.max(10,Math.min(58,n/Math.max(P,1)*75));
    const ground=`<line x1="50" y1="${yG}" x2="660" y2="${yG}" stroke="#a5b494" stroke-width="1"/><text x="625" y="282" class="diagram-small">지면</text>`;
    const wheels=`<circle cx="${xD}" cy="215" r="45" fill="#5b7656"/><circle cx="${xD}" cy="215" r="23" fill="#d6e0c4"/><circle cx="${xD}" cy="215" r="8" fill="#738c66"/><circle cx="${xC}" cy="236" r="24" fill="#9d885d"/><circle cx="${xC}" cy="236" r="10" fill="#e0d4af"/><line x1="${xC}" y1="214" x2="${xC}" y2="185" stroke="#8a7957" stroke-width="5"/><polyline points="${springPoints(xC,176,212,8,4)}" fill="none" stroke="#9f997f" stroke-width="2"/><text x="${xD}" y="304" text-anchor="middle">구동휠 배치 가정</text><text x="${xC}" y="304" text-anchor="middle">캐스터 현가부 해석</text>`;
    const frame=`<rect x="70" y="85" width="580" height="15" fill="#adb99b"/><line x1="350" y1="22" x2="350" y2="76" stroke="#71845f" stroke-width="2" marker-end="url(#arrow-neutral)"/><text x="362" y="41">분담하중 P = ${P.toFixed(0)} N</text>`;
    const linked=suspension.bogie?`<rect x="111" y="166" width="478" height="13" rx="5" fill="#c6b58e"/><line x1="${xD}" y1="179" x2="${xD}" y2="211" stroke="#b29b69" stroke-width="6"/><rect x="${xP-12}" y="100" width="24" height="65" fill="#839470"/><circle cx="${xP}" cy="172" r="12" fill="#edf0e4" stroke="#6e805d" stroke-width="4"/><text x="${xP+17}" y="142">보기 피벗 가정</text><line x1="${xD}" y1="128" x2="${xP}" y2="128" stroke="#a1ac8e" stroke-dasharray="3 4"/><text x="${(xD+xP)/2}" y="120" text-anchor="middle" class="diagram-small">a = ${pivot.toFixed(0)} mm</text><line x1="${xP}" y1="128" x2="${xC}" y2="128" stroke="#a1ac8e" stroke-dasharray="3 4"/><text x="${(xP+xC)/2}" y="120" text-anchor="middle" class="diagram-small">b = ${(span-pivot).toFixed(0)} mm</text>`:`<line x1="${xD}" y1="100" x2="${xD}" y2="171" stroke="#a6b095" stroke-dasharray="6 5" stroke-width="3"/><line x1="${xC}" y1="100" x2="${xC}" y2="171" stroke="#a6b095" stroke-dasharray="6 5" stroke-width="3"/><text x="350" y="145" text-anchor="middle" class="hypothesis-text">연결 구조 미정 · 하중 분배 계산 보류</text>`;
    const preload=suspension.preload&&suspension.bogie?`<polyline points="${springPoints(xS,103,161,8,5)}" fill="none" stroke="#b68d43" stroke-width="2" stroke-dasharray="5 2"/><line x1="${xS-17}" y1="110" x2="${xS-17}" y2="158" stroke="#b68d43" stroke-width="2" marker-end="url(#arrow-gold)"/><text x="${Math.max(55,xS-10)}" y="65" text-anchor="middle" class="hypothesis-text">추가 예압 F = ${F.toFixed(0)} N</text>`:'';
    const reactions=suspension.bogie?`<line x1="${xD-56}" y1="257" x2="${xD-56}" y2="${257-forceHeight(Nd)}" stroke="#678f57" stroke-width="3" marker-end="url(#arrow-green)"/><text x="${xD-62}" y="192" text-anchor="end" class="force-label">Nd</text>${valid?`<line x1="${xC+47}" y1="257" x2="${xC+47}" y2="${257-forceHeight(Nc)}" stroke="#a88a4c" stroke-width="3" marker-end="url(#arrow-gold)"/><text x="${xC+53}" y="208" class="hypothesis-text">Nc</text>`:`<path d="M ${xC-12} 250 l 24 18 M ${xC+12} 250 l -24 18" stroke="#ae603d" stroke-width="3"/><text x="${xC}" y="216" text-anchor="middle" class="hypothesis-text">접촉 가정 불성립</text>`}`:'';
    return `<defs><marker id="arrow-neutral" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#71845f"/></marker><marker id="arrow-green" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#678f57"/></marker><marker id="arrow-gold" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#b68d43"/></marker></defs>${ground}${frame}${linked}${wheels}${preload}${reactions}`;
  }

  window.renderSuspensionReview=()=>{
    for(const id of['bogie','preload'])$(id).checked=suspension[id];
    $('preload').disabled=!suspension.bogie;$('preload-force').disabled=!suspension.bogie;$('pivot-percent').disabled=!suspension.bogie;
    $('preload-force').value=suspension.preload?suspension.springForce:0;$('pivot-percent').value=suspension.pivotPct;
    const span=params.L/2-90,pivot=span*suspension.pivotPct/100,mass=+$('mass').value,F=suspension.preload?suspension.springForce:0;
    const x5=coordinates().rear.positions[0][0],xG=+$('cg-x').value,W=mass*9.81,M=F*suspension.lever;
    const P=(W*(xG-x5)+2*M)/(2*(pivot-x5)),N5=W-2*P,Nd=(P*(span-pivot)+M)/span,Nc=P-Nd;
    const valid=P>0&&Nd>0&&Nc>0&&N5>0;
    $('preload-force-out').textContent=suspension.preload?`${F} N`:'추가 예압 끔 / 0 N';$('pivot-out').textContent=`${suspension.pivotPct}% / a=${pivot.toFixed(0)} mm`;$('cg-out').textContent=`${xG} mm`;
    $('model-status').innerHTML=`<b>5휠: 구동 2 + 전방 현가 캐스터 2 + 후방 중앙 캐스터 1</b><br>사진 반영: 검은 캡·노출 코일·14S4P 배터리·은색 고정대 / 보기 연결 ${suspension.bogie?'적용':'해제'} / 추가 구동륜 예압 ${suspension.preload?'검토 중':'끔'}`;
    if(!Number.isFinite(mass)||mass<80||mass>250){$('bogie-diagram').innerHTML='<text x="360" y="160" text-anchor="middle">총질량은 80–250 kg로 입력하세요.</text>';$('reaction-bars').innerHTML='';$('suspension-results').textContent='질량 입력 확인';return;}
    $('bogie-diagram').innerHTML=diagram(P,Nd,Nc,span,pivot,F,valid);
    if(!suspension.bogie){$('reaction-bars').innerHTML='<p class="reaction-invalid">독립 현가 5점의 하중 분담은 각 현가의 강성·예압·변위가 필요하므로 현재 계산하지 않습니다.</p>';$('suspension-results').textContent='5휠 형상은 유지합니다. 계산하려면 보기 연결 가설을 켜세요.';return;}
    $('reaction-bars').innerHTML=valid?[['구동휠 2개 합계',2*Nd,''],['전방 현가 캐스터 2개 합계',2*Nc,'caster-fill'],['후방 중앙 캐스터 1개',N5,'caster-fill']].map(([label,n,cl])=>`<div><div class="reaction-label"><span>${label}</span><span>${n.toFixed(1)} N / ${(n/W*100).toFixed(1)}%</span></div><div class="reaction-track"><div class="reaction-fill ${cl}" style="width:${n/W*100}%"></div></div></div>`).join(''):`<p class="reaction-invalid">5점 접촉 가정 불성립: Nd=${Nd.toFixed(1)}, Nc=${Nc.toFixed(1)}, N5=${N5.toFixed(1)} N. 하나 이상의 휠 반력이 0 이하입니다. 접촉 전환 이후는 계산하지 않습니다.</p>`;
    $('suspension-results').innerHTML=valid?`보기 1조 P <b>${P.toFixed(1)} N</b><br>구동휠 1개 <b>${Nd.toFixed(1)} N</b> / 전방 캐스터 1개 <b>${Nc.toFixed(1)} N</b><br>후방 중앙 N5 <b>${N5.toFixed(1)} N</b><br><span class="ok">수직력 합계 ${(2*Nd+2*Nc+N5).toFixed(1)} N = mg</span><br><span class="ok">전후 모멘트 잔차 ${((2*Nc*span+N5*x5-W*xG)/1000).toFixed(3)} N·m</span>`:'<span class="warn">예압·피벗·무게중심을 조정해 모든 휠 반력을 양수로 유지하세요.</span>';
    const cgY=massAnalysis().cg[1];if(Math.abs(cgY)>1)$('suspension-results').innerHTML+=`<p class="warn">CG Y=${cgY.toFixed(1)} mm: 이 표는 Y=0으로 투영한 좌우 대칭 참고값입니다. 실제 좌우 휠 반력은 계산하지 않았습니다.</p>`;
  };
  for(const id of['bogie','preload'])$(id).addEventListener('change',()=>{suspension[id]=$(id).checked;if(!suspension.bogie)suspension.preload=false;window.renderSuspensionReview();draw();});
  $('preload-force').addEventListener('input',()=>{suspension.springForce=+$('preload-force').value;suspension.preload=suspension.springForce>0;window.renderSuspensionReview();draw();});
  $('pivot-percent').addEventListener('input',()=>{suspension.pivotPct=+$('pivot-percent').value;window.renderSuspensionReview();draw();});
  $('cg-x').addEventListener('input',()=>window.renderSuspensionReview());
  $('rear-focus').addEventListener('click',()=>{select('rear');setView('side');$('model').scrollIntoView({behavior:'smooth',block:'center'});});
  $('plan-view-link').addEventListener('click',()=>setView('top'));
  showObservation('battery');window.renderSuspensionReview();
})();
